import React, { useMemo } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Divider,
  Grid,
  Typography,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  GHG_SCOPE_COLORS,
  GHG_SCOPE_HEX,
  formatAxisTickKg,
  maxKgFromRows,
  rechartsCountTooltipFormatter,
  rechartsEmissionsTooltipFormatter,
  rechartsKgValueAxisLabelProps,
  rechartsPercentAxisLabelProps,
  rechartsPercentTooltipFormatter,
} from '../../constants/carbonVisualization';
import {
  axisTickForMode,
  cartesianGridStroke,
  chartAnimationPropsFor,
  rechartsLegendProps,
  rechartsTooltipProps,
} from '../../theme/rechartsAppearances';
import { usePrefersReducedMotion } from '../../hooks/usePrefersReducedMotion';
import {
  buildBenchmarkBulletRows,
  buildHotspotLollipops,
  complianceDonutSegments,
} from '../../utils/carbonAnalyticsChartData';
import QuantificationMethodBanner from '../shared/QuantificationMethodBanner';
import InventoryChecksPanel from '../shared/InventoryChecksPanel';
import CalculationAnalyticsCharts from '../shared/CalculationAnalyticsCharts';
import CarbonChartFrame from '../shared/CarbonChartFrame';
import {
  cartesianMarginsForKgAxis,
  pieChartCenterProps,
} from '../../constants/carbonVisualization';

export type ReportingCarbonFootprintPayload = {
  carbonData?: Array<{ month?: string; carbonFootprint?: number; target?: number }>;
  categoryData?: Array<{ name?: string; value?: number }>;
  scopeData?: {
    scope1?: { total?: number; percentage?: number };
    scope2?: { total?: number; percentage?: number };
    scope3?: { total?: number; percentage?: number };
    total?: number;
  };
  quantificationSummary?: {
    activitySharePct?: number;
    spendBasedSharePct?: number;
    tier1SharePct?: number;
    tier2SharePct?: number;
    tier3SharePct?: number;
    primaryBasis?: 'activity_based' | 'spend_based';
    uncertaintyNote?: string;
    inventoryChecks?: Array<{
      check: string;
      transactions: number;
      includedTransactions: number;
      kgCo2e: number;
      shareOfIncludedKgPercent: number;
      meaning?: string;
    }>;
    scopes?: { scope1Kg?: number; scope2Kg?: number; scope3Kg?: number; totalKg?: number };
    isoCategories?: Array<{ id?: string; label: string; kgCo2e: number }>;
    isoSubcategories?: Array<{ category?: string; subcategory: string; kgCo2e: number; transactions?: number }>;
    unallocatedScope3Kg?: number;
    excludedCount?: number;
    outsideToleranceCount?: number;
    applicationCategories?: Array<{ label: string; transactions?: number; kgCo2e?: number; shareOfIncludedKgPercent?: number }>;
    vendors?: Array<{ label: string; transactions?: number; kgCo2e?: number; shareOfIncludedKgPercent?: number }>;
    months?: Array<{ period: string; transactions?: number; scope1Kg?: number; scope2Kg?: number; scope3Kg?: number; kgCo2e?: number }>;
    companyNotes?: string[];
    isoScope3Categories?: Array<{ number?: number; category: string; kgCo2e?: number; isoPlacement?: string }>;
    isoScope3Subcategories?: Array<{ category?: string; subcategory: string; kgCo2e?: number }>;
  };
};

export type ReportingComparisonsPayload = {
  industryAverage?: number;
  userPerformance?: number;
  previousAssessmentEmissionsTonnes?: number;
  benchmarkData?: Array<{ category?: string; user?: number; industry?: number }>;
};

type HotspotRow = {
  rank: number;
  hotspot: string;
  emissionsKgCO2e: number;
  sharePercent: number;
};

type ValueChainStage = {
  label: string;
  contributionPercent: number;
};

export type ReportingCarbonAnalyticsPanelProps = {
  footprint: ReportingCarbonFootprintPayload | null;
  comparisons: ReportingComparisonsPayload | null;
  hotspots?: HotspotRow[];
  valueChainStages?: ValueChainStage[];
  sectorFocus?: Array<{ label: string; emissionsKgCO2e: number }>;
  isoComplianceChecks?: Array<{ id: string; label?: string; status: string; score?: number }>;
  totalEmissionsKg?: number;
  /** When false, hides the outer title block (e.g. when embedded in reports with its own heading). */
  showHeader?: boolean;
};

function AnalyticsSection({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: subtitle ? 0.5 : 1.5 }}>
        {title}
      </Typography>
      {subtitle ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1.5, maxWidth: 820 }}>
          {subtitle}
        </Typography>
      ) : null}
      <Grid container spacing={3}>
        {children}
      </Grid>
    </Box>
  );
}

const ReportingCarbonAnalyticsPanel: React.FC<ReportingCarbonAnalyticsPanelProps> = ({
  footprint,
  comparisons,
  hotspots = [],
  valueChainStages = [],
  sectorFocus = [],
  isoComplianceChecks = [],
  totalEmissionsKg,
  showHeader = true,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const chartGrid = cartesianGridStroke(isDark);
  const chartTip = rechartsTooltipProps(isDark);
  const tickAxis = axisTickForMode(isDark);
  const chartMotion = chartAnimationPropsFor(usePrefersReducedMotion());
  const valueChainAxisTick = (tickProps: { x?: number; y?: number; payload?: { value?: string } }) => {
    const x = Number(tickProps.x) || 0;
    const y = Number(tickProps.y) || 0;
    const full = String(tickProps.payload?.value || '');
    const paren = full.indexOf('(');
    const head = (paren >= 0 ? full.slice(0, paren) : full).trim();
    const detail = paren >= 0 ? full.slice(paren).trim() : '';
    return (
      <text x={x} y={y} textAnchor="middle" fill={tickAxis.fill} fontSize={10}>
        <tspan x={x} dy={14}>{head}</tspan>
        {detail ? (
          <tspan x={x} dy={12}>{detail}</tspan>
        ) : null}
      </text>
    );
  };

  const scopePie = useMemo(() => {
    const s = footprint?.scopeData;
    const buildRows = (scope1: number, scope2: number, scope3: number) => [
      { name: 'Scope 1', value: scope1 },
      { name: 'Scope 2', value: scope2 },
      { name: 'Scope 3', value: scope3 },
    ].filter((row) => row.value > 0);

    if (s) {
      const direct = buildRows(
        Number(s.scope1?.total) || 0,
        Number(s.scope2?.total) || 0,
        Number(s.scope3?.total) || 0,
      );
      if (direct.length > 0) {
        return direct;
      }

      const total = Number(s.total) || Number(totalEmissionsKg) || 0;
      const p1 = Number(s.scope1?.percentage) || 0;
      const p2 = Number(s.scope2?.percentage) || 0;
      const p3 = Number(s.scope3?.percentage) || 0;
      const pctSum = p1 + p2 + p3;
      if (total > 0 && pctSum > 0) {
        return buildRows(
          (p1 / pctSum) * total,
          (p2 / pctSum) * total,
          (p3 / pctSum) * total,
        );
      }
    }

    return [];
  }, [footprint?.scopeData, totalEmissionsKg]);

  const trendRows = useMemo(
    () =>
      (footprint?.carbonData || [])
        .map((row) => ({
          period: String(row.month || ''),
          emissions: Number(row.carbonFootprint) || 0,
          target: Number(row.target) || 0,
        }))
        .filter((row) => row.period),
    [footprint?.carbonData]
  );

  const hotspotChart = useMemo(
    () =>
      buildHotspotLollipops(
        hotspots.map((h) => ({
          id: `h-${h.rank}`,
          label: h.hotspot,
          co2: h.emissionsKgCO2e,
        }))
      ),
    [hotspots]
  );

  const benchmarkRows = useMemo(() => {
    const total = Number(totalEmissionsKg) || Number(footprint?.scopeData?.total) || 0;
    const previousKg =
      comparisons?.previousAssessmentEmissionsTonnes != null
        ? Number(comparisons.previousAssessmentEmissionsTonnes) * 1000
        : 0;
    return buildBenchmarkBulletRows(total, {
      industryAverageKg: (Number(comparisons?.industryAverage) || 0) * 1000,
      previousAssessmentKg: previousKg,
    });
  }, [
    comparisons?.industryAverage,
    comparisons?.previousAssessmentEmissionsTonnes,
    footprint?.scopeData?.total,
    totalEmissionsKg,
  ]);

  const complianceDonut = useMemo(
    () =>
      complianceDonutSegments(
        isoComplianceChecks.map((c) => ({
          status: c.status === 'pass' || c.status === 'Pass'
            ? 'pass'
            : c.status === 'warning' || c.status === 'Warning'
              ? 'warning'
              : 'gap',
        }))
      ),
    [isoComplianceChecks]
  );

  const sectorBar = useMemo(
    () =>
      [...sectorFocus]
        .filter((c) => Number(c.emissionsKgCO2e) > 0)
        .sort((a, b) => b.emissionsKgCO2e - a.emissionsKgCO2e)
        .slice(0, 8),
    [sectorFocus]
  );

  const valueChainBar = useMemo(
    () => valueChainStages.filter((s) => Number(s.contributionPercent) > 0),
    [valueChainStages]
  );

  const maxTrend = Math.max(...trendRows.map((r) => Math.max(r.emissions, r.target)), 1);
  const hotspotMaxKg = maxKgFromRows(hotspotChart, (r) => Number(r.emissions) || 0);
  const sectorMaxKg = maxKgFromRows(sectorBar, (r) => Number(r.emissionsKgCO2e) || 0);
  const benchmarkMaxKg = maxKgFromRows(benchmarkRows, (r) => Number(r.value) || 0);

  const hasInventorySection = scopePie.length > 0 || trendRows.length > 0;
  const hasHotspotSection = hotspotChart.length > 0 || sectorBar.length > 0;
  const hasValueChainSection = valueChainBar.length > 0 || complianceDonut.length > 0;
  const hasBenchmarkSection = benchmarkRows.length > 0;

  const hasAnyChart =
    hasInventorySection || hasHotspotSection || hasValueChainSection || hasBenchmarkSection
    || (footprint?.quantificationSummary?.inventoryChecks || []).length > 0
    || (footprint?.quantificationSummary?.isoCategories || []).length > 0;

  if (!hasAnyChart) {
    return (
      <Alert severity="info" sx={{ mb: 2 }}>
        Complete a carbon assessment for this period to unlock GHG scope analytics, sector hotspots, and benchmark
        comparisons aligned to disclosure standards.
      </Alert>
    );
  }

  return (
    <Box sx={{ mb: 3 }}>
      {showHeader ? (
        <>
          <Typography variant="h6" gutterBottom>
            Carbon analytics (reporting period)
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
            {CO2E_METHODOLOGY_SUBTITLE} Charts follow disclosure order: inventory overview, hotspots, value chain, then
            benchmarks. Export and print use the same layout.
          </Typography>
        </>
      ) : null}

      <QuantificationMethodBanner summary={footprint?.quantificationSummary} />
      <CalculationAnalyticsCharts analytics={footprint?.quantificationSummary} />
      <Box sx={{ mb: 3 }}>
        <InventoryChecksPanel checks={footprint?.quantificationSummary?.inventoryChecks} />
      </Box>

      {hasInventorySection ? (
        <AnalyticsSection
          title="1. GHG inventory overview"
          subtitle={(() => {
            const withTarget = trendRows.filter((r) => r.target > 0 && r.emissions > 0);
            const sample = withTarget[0];
            const pct = sample
              ? Math.round((1 - sample.target / sample.emissions) * 100)
              : null;
            return pct != null && pct > 0 && pct < 80
              ? `Scope split and footprint trajectory against a ${pct}% reduction target for the selected reporting period.`
              : 'Scope split and footprint trajectory against your configured reduction target for the selected reporting period.';
          })()}
        >
          {scopePie.length > 0 && (
            <Grid item xs={12} md={4}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    Scope inventory split
                  </Typography>
                  <CarbonChartFrame
                    height={280}
                    unitKind="emissionsKg"
                    ariaLabel="Pie chart of scope one two and three emissions in kilograms CO2 equivalent."
                  >
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart margin={{ top: 12, right: 72, bottom: 4, left: 72 }}>
                        <Pie
                          data={scopePie}
                          dataKey="value"
                          nameKey="name"
                          innerRadius={40}
                          outerRadius={58}
                          paddingAngle={2}
                          {...pieChartCenterProps}
                          cy="44%"
                          labelLine={false}
                          label={(entry: {
                            name?: string;
                            percent?: number;
                            cx?: number;
                            cy?: number;
                            midAngle?: number;
                            outerRadius?: number;
                          }) => {
                            const cx = Number(entry.cx) || 0;
                            const cy = Number(entry.cy) || 0;
                            const midAngle = Number(entry.midAngle) || 0;
                            const radius = (Number(entry.outerRadius) || 0) + 16;
                            const rad = (-midAngle * Math.PI) / 180;
                            const x = cx + radius * Math.cos(rad);
                            const y = cy + radius * Math.sin(rad);
                            const pct = Math.round((Number(entry.percent) || 0) * 100);
                            return (
                              <text
                                x={x}
                                y={y}
                                fill={tickAxis.fill}
                                fontSize={11}
                                textAnchor={x > cx ? 'start' : 'end'}
                                dominantBaseline="central"
                              >
                                {`${entry.name} ${pct}%`}
                              </text>
                            );
                          }}
                          {...chartMotion}
                        >
                        {scopePie.map((row) => {
                          const sk = (
                            row.name === 'Scope 1' ? 'scope1'
                              : row.name === 'Scope 2' ? 'scope2'
                                : 'scope3'
                          ) as 'scope1' | 'scope2' | 'scope3';
                          return (
                            <Cell
                              key={row.name}
                              fill={GHG_SCOPE_HEX[sk]}
                              stroke={GHG_SCOPE_COLORS[sk].stroke}
                              strokeWidth={1.5}
                            />
                          );
                        })}
                      </Pie>
                      <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                      <Legend
                        {...rechartsLegendProps}
                        wrapperStyle={{ ...rechartsLegendProps.wrapperStyle, paddingTop: 16 }}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                  </CarbonChartFrame>
                </CardContent>
              </Card>
            </Grid>
          )}

          {trendRows.length > 0 && (
            <Grid item xs={12} md={scopePie.length > 0 ? 8 : 12}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    Emissions trend vs target
                  </Typography>
                  <CarbonChartFrame
                    height={240}
                    unitKind="emissionsKg"
                    ariaLabel="Area chart of carbon footprint emissions trend versus reduction target in kilograms CO2 equivalent."
                  >
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart
                        data={trendRows}
                        margin={cartesianMarginsForKgAxis(maxTrend)}
                      >
                      <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                      <XAxis dataKey="period" tick={tickAxis} />
                      <YAxis
                        tick={tickAxis}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={{
                          ...rechartsKgValueAxisLabelProps(maxTrend, { fill: tickAxis.fill as string }),
                          style: { fontSize: 10, fill: tickAxis.fill as string },
                        }}
                      />
                      <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                      <Legend {...rechartsLegendProps} />
                      <Area
                        type="monotone"
                        dataKey="emissions"
                        stroke={GHG_SCOPE_HEX.scope2}
                        fill={GHG_SCOPE_HEX.scope2}
                        fillOpacity={0.35}
                        name="Footprint (kg CO₂e)"
                        {...chartMotion}
                      />
                      <Area
                        type="monotone"
                        dataKey="target"
                        stroke="#94a3b8"
                        fill="#94a3b8"
                        fillOpacity={0.15}
                        name="Target (kg CO₂e)"
                        {...chartMotion}
                      />
                    </AreaChart>
                  </ResponsiveContainer>
                  </CarbonChartFrame>
                </CardContent>
              </Card>
            </Grid>
          )}
        </AnalyticsSection>
      ) : null}

      {hasHotspotSection ? (
        <>
          {hasInventorySection ? <Divider sx={{ mb: 3 }} /> : null}
          <AnalyticsSection
            title="2. Hotspots & sector focus"
            subtitle="Highest-impact sources for BRSR Principle 6 mitigation planning and sector-weighted categories."
          >
            {hotspotChart.length > 0 && (
              <Grid item xs={12} md={6}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Typography variant="subtitle2" gutterBottom>
                      Emission hotspots (BRSR)
                    </Typography>
                    <CarbonChartFrame
                      height={260}
                      unitKind="emissionsKg"
                      ariaLabel="Horizontal bar chart of top emission hotspots in kilograms CO2 equivalent."
                    >
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart
                          data={hotspotChart}
                          layout="vertical"
                          margin={{ top: 4, right: 16, left: 8, bottom: 20 }}
                        >
                        <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} horizontal={false} />
                        <XAxis
                          type="number"
                          tick={tickAxis}
                          tickFormatter={(v: number) => formatAxisTickKg(v)}
                          label={rechartsKgValueAxisLabelProps(hotspotMaxKg, {
                            fill: tickAxis.fill as string,
                            vertical: false,
                          })}
                        />
                        <YAxis type="category" dataKey="label" width={120} tick={tickAxis} />
                        <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                        <Bar dataKey="emissions" name="kg CO₂e" fill="#0d9488" radius={[0, 6, 6, 0]} {...chartMotion} />
                      </BarChart>
                    </ResponsiveContainer>
                    </CarbonChartFrame>
                  </CardContent>
                </Card>
              </Grid>
            )}

            {sectorBar.length > 0 && (
              <Grid item xs={12} md={6}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Typography variant="subtitle2" gutterBottom>
                      Sector focus categories
                    </Typography>
                    <CarbonChartFrame
                      height={260}
                      unitKind="emissionsKg"
                      ariaLabel="Bar chart of sector focus category emissions in kilograms CO2 equivalent."
                    >
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart
                          data={sectorBar}
                          margin={cartesianMarginsForKgAxis(sectorMaxKg)}
                        >
                        <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                        <XAxis dataKey="label" interval={0} angle={-14} textAnchor="end" height={64} tick={tickAxis} />
                        <YAxis
                          tick={tickAxis}
                          tickFormatter={(v: number) => formatAxisTickKg(v)}
                          label={{
                            ...rechartsKgValueAxisLabelProps(sectorMaxKg, { fill: tickAxis.fill as string }),
                            style: { fontSize: 10, fill: tickAxis.fill as string },
                          }}
                        />
                        <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                        <Bar
                          dataKey="emissionsKgCO2e"
                          fill="#0284c7"
                          name="kg CO₂e"
                          radius={[6, 6, 0, 0]}
                          {...chartMotion}
                        />
                      </BarChart>
                    </ResponsiveContainer>
                    </CarbonChartFrame>
                  </CardContent>
                </Card>
              </Grid>
            )}
          </AnalyticsSection>
        </>
      ) : null}

      {hasValueChainSection ? (
        <>
          {(hasInventorySection || hasHotspotSection) ? <Divider sx={{ mb: 3 }} /> : null}
          <AnalyticsSection
            title="3. Value chain & compliance"
            subtitle="Stage-level contribution across your value chain and ISO 14064 readiness checks."
          >
            {valueChainBar.length > 0 && (
              <Grid item xs={12} md={6}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Typography variant="subtitle2" gutterBottom>
                      Value chain stage contribution
                    </Typography>
                    <CarbonChartFrame
                      height={320}
                      unitKind="emissionsPercent"
                      ariaLabel="Bar chart of value chain stage contribution as percent of total emissions."
                    >
                      <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={valueChainBar} margin={{ top: 8, right: 12, left: 8, bottom: 28 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                        <XAxis
                          dataKey="label"
                          interval={0}
                          height={64}
                          tick={valueChainAxisTick}
                        />
                        <YAxis
                          tick={tickAxis}
                          domain={[0, 100]}
                          tickFormatter={(v: number) => `${v}%`}
                          label={{
                            ...rechartsPercentAxisLabelProps({ fill: tickAxis.fill as string }),
                            style: { fontSize: 10, fill: tickAxis.fill as string },
                          }}
                        />
                        <Tooltip {...chartTip} formatter={rechartsPercentTooltipFormatter} />
                        <Bar
                          dataKey="contributionPercent"
                          fill="#7c3aed"
                          name="% of total"
                          radius={[6, 6, 0, 0]}
                          {...chartMotion}
                        />
                      </BarChart>
                    </ResponsiveContainer>
                    </CarbonChartFrame>
                  </CardContent>
                </Card>
              </Grid>
            )}

            {complianceDonut.length > 0 && (
              <Grid item xs={12} md={6}>
                <Card sx={{ height: '100%' }}>
                  <CardContent>
                    <Typography variant="subtitle2" gutterBottom>
                      ISO 14064 compliance checks
                    </Typography>
                    <CarbonChartFrame
                      height={240}
                      unitKind="none"
                      unitCaption="Count of ISO 14064 compliance checks in each status."
                      ariaLabel="Donut chart of ISO 14064 automated compliance check outcomes."
                    >
                      <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={complianceDonut}
                          dataKey="value"
                          nameKey="name"
                          innerRadius={48}
                          outerRadius={80}
                          paddingAngle={2}
                          {...chartMotion}
                        >
                          {complianceDonut.map((entry, idx) => (
                            <Cell key={entry.name} fill={['#059669', '#f59e0b', '#94a3b8'][idx % 3]} />
                          ))}
                        </Pie>
                        <Tooltip {...chartTip} formatter={rechartsCountTooltipFormatter} />
                        <Legend {...rechartsLegendProps} />
                      </PieChart>
                    </ResponsiveContainer>
                    </CarbonChartFrame>
                  </CardContent>
                </Card>
              </Grid>
            )}
          </AnalyticsSection>
        </>
      ) : null}

      {hasBenchmarkSection ? (
        <>
          {(hasInventorySection || hasHotspotSection || hasValueChainSection) ? <Divider sx={{ mb: 3 }} /> : null}
          <AnalyticsSection
            title="4. Benchmarking"
            subtitle="Compare your footprint against previous assessments and industry references where configured."
          >
            <Grid item xs={12} md={8}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    Performance vs industry benchmark
                  </Typography>
                  <CarbonChartFrame
                    height={240}
                    unitKind="emissionsKg"
                    ariaLabel="Bar chart comparing your footprint against industry benchmark and previous assessment in kilograms CO2 equivalent."
                  >
                    <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={benchmarkRows} margin={{ top: 8, right: 8, left: 0, bottom: 4 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={chartGrid} vertical={false} />
                      <XAxis dataKey="label" tick={tickAxis} />
                      <YAxis
                        tick={tickAxis}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={{
                          ...rechartsKgValueAxisLabelProps(benchmarkMaxKg, { fill: tickAxis.fill as string }),
                          style: { fontSize: 10, fill: tickAxis.fill as string },
                        }}
                      />
                      <Tooltip {...chartTip} formatter={rechartsEmissionsTooltipFormatter} />
                      <Bar dataKey="value" name="kg CO₂e" radius={[6, 6, 0, 0]} {...chartMotion}>
                        {benchmarkRows.map((row) => (
                          <Cell
                            key={`${row.kind}-${row.label}`}
                            fill={
                              row.kind === 'industry' ? '#2563eb'
                                : row.kind === 'previous' ? '#d97706'
                                  : row.kind === 'best' ? '#059669'
                                    : '#0d9488'
                            }
                          />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                  </CarbonChartFrame>
                </CardContent>
              </Card>
            </Grid>
          </AnalyticsSection>
        </>
      ) : null}
    </Box>
  );
};

export default ReportingCarbonAnalyticsPanel;
