import React, { useMemo } from 'react';
import { Box, Grid, Paper, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { GHG_SCOPE_HEX } from '../../constants/carbonVisualization';
import { chartAnimationPropsFor, rechartsTooltipProps } from '../../theme/rechartsAppearances';
import { usePrefersReducedMotion } from '../../hooks/usePrefersReducedMotion';

export type CalculationAnalytics = {
  scopes?: {
    scope1Kg?: number;
    scope2Kg?: number;
    scope3Kg?: number;
    totalKg?: number;
  };
  isoCategories?: Array<{ id?: string; label?: string; kgCo2e?: number }>;
  isoSubcategories?: Array<{
    category?: string;
    subcategory?: string;
    kgCo2e?: number;
    transactions?: number;
  }>;
  unallocatedScope3Kg?: number;
  inventoryChecks?: Array<{ check: string; transactions: number; kgCo2e?: number }>;
  excludedCount?: number;
  outsideToleranceCount?: number;
  applicationCategories?: Array<{ label: string; transactions?: number; kgCo2e?: number; shareOfIncludedKgPercent?: number }>;
  vendors?: Array<{ label: string; transactions?: number; kgCo2e?: number; shareOfIncludedKgPercent?: number }>;
  months?: Array<{ period: string; transactions?: number; scope1Kg?: number; scope2Kg?: number; scope3Kg?: number; kgCo2e?: number }>;
  companyNotes?: string[];
  isoScope3Categories?: Array<{
    number?: number;
    category: string;
    isoPlacement?: string;
    transactions?: number;
    kgCo2e?: number;
    shareOfScope3Percent?: number;
  }>;
  isoScope3Subcategories?: Array<{
    number?: number;
    category?: string;
    subcategory: string;
    transactions?: number;
    kgCo2e?: number;
  }>;
};

const SCOPE_COLORS = [GHG_SCOPE_HEX.scope1, GHG_SCOPE_HEX.scope2, GHG_SCOPE_HEX.scope3];
const ISO_COLOR = '#0F766E';
const COUNT_COLOR = '#1E3A5F';

const checkCount = (checks: CalculationAnalytics['inventoryChecks'], label: string) => {
  const row = (checks || []).find((item) => item.check === label);
  return Number(row?.transactions) || 0;
};

const checkKg = (checks: CalculationAnalytics['inventoryChecks'], label: string) => {
  const row = (checks || []).find((item) => item.check === label);
  return Number(row?.kgCo2e) || 0;
};

const shortIsoLabel = (label: string) => {
  const match = String(label || '').match(/Category\s+(\d)/i);
  return match ? `Category ${match[1]}` : label;
};

type CalculationAnalyticsChartsProps = {
  analytics?: CalculationAnalytics | null;
};

const ChartCard = ({
  title,
  subtitle,
  children,
  testId,
}: {
  title: string;
  subtitle: string;
  children: React.ReactNode;
  testId: string;
}) => (
  <Paper variant="outlined" sx={{ p: 2, height: '100%' }} data-testid={testId}>
    <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{title}</Typography>
    <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
      {subtitle}
    </Typography>
    {children}
  </Paper>
);

const CalculationAnalyticsCharts: React.FC<CalculationAnalyticsChartsProps> = ({ analytics }) => {
  const theme = useTheme();
  const reducedMotion = usePrefersReducedMotion();
  const animation = chartAnimationPropsFor(reducedMotion);
  const tooltipProps = rechartsTooltipProps(theme.palette.mode === 'dark');

  const scopeRows = useMemo(() => ([
    { label: 'Scope 1', kg: Number(analytics?.scopes?.scope1Kg) || 0 },
    { label: 'Scope 2', kg: Number(analytics?.scopes?.scope2Kg) || 0 },
    { label: 'Scope 3', kg: Number(analytics?.scopes?.scope3Kg) || 0 },
  ]), [analytics?.scopes]);

  const categoryRows = useMemo(() => {
    const rows = (analytics?.isoCategories || []).map((row) => ({
      label: shortIsoLabel(row.label || ''),
      full: row.label || '',
      kg: Number(row.kgCo2e) || 0,
    }));
    const unallocated = Number(analytics?.unallocatedScope3Kg) || 0;
    if (unallocated) rows.push({ label: 'Unallocated', full: 'Unallocated Scope 3', kg: unallocated });
    return rows;
  }, [analytics?.isoCategories, analytics?.unallocatedScope3Kg]);

  const subcategoryRows = useMemo(() => (
    (analytics?.isoSubcategories || [])
      .filter((row) => Number(row.kgCo2e) > 0)
      .sort((left, right) => Number(right.kgCo2e) - Number(left.kgCo2e))
      .slice(0, 12)
      .map((row) => ({
        label: row.subcategory || '',
        kg: Number(row.kgCo2e) || 0,
        transactions: Number(row.transactions) || 0,
      }))
  ), [analytics?.isoSubcategories]);

  const countRows = useMemo(() => ([
    { label: 'Activity-based', count: checkCount(analytics?.inventoryChecks, 'Activity-based') },
    { label: 'Spend-based', count: checkCount(analytics?.inventoryChecks, 'Spend-based') },
    { label: 'Estimate', count: checkCount(analytics?.inventoryChecks, 'Estimate') },
    { label: 'Excluded', count: Number(analytics?.excludedCount) || checkCount(analytics?.inventoryChecks, 'Excluded') },
    { label: 'Outside tolerance', count: Number(analytics?.outsideToleranceCount) || checkCount(analytics?.inventoryChecks, 'Outside tolerance') },
  ]), [analytics]);

  const qualityRows = useMemo(() => ([
    { label: 'Tier 1 activity', kg: checkKg(analytics?.inventoryChecks, 'Data quality: Tier 1 — activity') },
    { label: 'Tier 2 spend', kg: checkKg(analytics?.inventoryChecks, 'Data quality: Tier 2 — spend') },
    { label: 'Tier 3 estimate', kg: checkKg(analytics?.inventoryChecks, 'Data quality: Tier 3 — estimate') },
  ]), [analytics?.inventoryChecks]);

  const sourceRows = (rows?: CalculationAnalytics['applicationCategories']) => (
    (rows || [])
      .filter((row) => Number(row.kgCo2e) > 0 && row.label !== 'Not stated')
      .slice(0, 8)
      .map((row) => ({ label: row.label, kg: Number(row.kgCo2e) || 0 }))
  );

  const categoryHotspots = useMemo(() => sourceRows(analytics?.applicationCategories), [analytics?.applicationCategories]);
  const vendorHotspots = useMemo(() => sourceRows(analytics?.vendors), [analytics?.vendors]);
  const monthRows = useMemo(() => (
    (analytics?.months || []).map((row) => ({
      label: row.period,
      kg: Number(row.kgCo2e) || 0,
    }))
  ), [analytics?.months]);

  const scope3CategoryRows = useMemo(() => (
    (analytics?.isoScope3Categories || []).map((row) => ({
      label: `Cat ${row.number}`,
      full: row.category,
      kg: Number(row.kgCo2e) || 0,
    }))
  ), [analytics?.isoScope3Categories]);

  const scope3SubcategoryRows = useMemo(() => (
    (analytics?.isoScope3Subcategories || [])
      .filter((row) => Number(row.kgCo2e) > 0)
      .sort((left, right) => Number(right.kgCo2e) - Number(left.kgCo2e))
      .slice(0, 15)
      .map((row) => ({
        label: row.subcategory,
        full: `${row.category || ''} — ${row.subcategory}`,
        kg: Number(row.kgCo2e) || 0,
      }))
  ), [analytics?.isoScope3Subcategories]);

  const hasScope = scopeRows.some((row) => row.kg > 0);
  const hasCategory = categoryRows.some((row) => row.kg > 0);
  const hasCounts = countRows.some((row) => row.count > 0) || (analytics?.inventoryChecks || []).length > 0;
  const hasQuality = qualityRows.some((row) => row.kg > 0);
  const notes = analytics?.companyNotes || [];
  const hasScope3Categories = scope3CategoryRows.length > 0;
  if (!hasScope && !hasCategory && !hasCounts && !hasQuality && categoryHotspots.length === 0 && !hasScope3Categories) return null;

  return (
    <Box data-testid="calculation-analytics-charts" sx={{ mb: 2 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 0.5 }}>
        Inventory analytics
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Same figures as the Analytics sheet in the transaction audit workbook.
      </Typography>
      <Grid container spacing={2}>
        {hasScope ? (
          <Grid item xs={12} md={4}>
            <ChartCard
              testId="analytics-scope-chart"
              title="GHG Protocol scopes"
              subtitle="Included kilograms in Scope 1, Scope 2, and Scope 3."
            >
              <Box sx={{ height: 220 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={scopeRows} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 12 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" radius={[4, 4, 0, 0]} {...animation}>
                      {scopeRows.map((row, index) => (
                        <Cell key={row.label} fill={SCOPE_COLORS[index % SCOPE_COLORS.length]} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {hasCategory ? (
          <Grid item xs={12} md={8}>
            <ChartCard
              testId="analytics-iso-chart"
              title="ISO 14064-1 categories"
              subtitle="Clause 5.2.4 categories from the same included inventory."
            >
              <Box sx={{ height: 220 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={categoryRows} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip
                      {...tooltipProps}
                      formatter={(value: number, _name, item) => [
                        `${Number(value).toLocaleString()} kg CO₂e`,
                        item?.payload?.full || 'Category',
                      ]}
                    />
                    <Bar dataKey="kg" fill={ISO_COLOR} radius={[4, 4, 0, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {hasScope3Categories ? (
          <Grid item xs={12}>
            <ChartCard
              testId="analytics-scope3-category-chart"
              title="ISO 14064 Scope 3 categories 1 to 15"
              subtitle="GHG Protocol Scope 3 categories placed under ISO 14064-1 Categories 3 to 6."
            >
              <Box sx={{ height: Math.max(280, scope3CategoryRows.length * 24) }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={scope3CategoryRows} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={64} tick={{ fontSize: 11 }} />
                    <Tooltip
                      {...tooltipProps}
                      formatter={(value: number, _name, item) => [
                        `${Number(value).toLocaleString()} kg CO₂e`,
                        item?.payload?.full || 'Scope 3',
                      ]}
                    />
                    <Bar dataKey="kg" fill={ISO_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {scope3SubcategoryRows.length > 0 ? (
          <Grid item xs={12}>
            <ChartCard
              testId="analytics-scope3-subcategory-chart"
              title="ISO 14064 Scope 3 subcategories"
              subtitle="Named calculations under categories 1 to 15 that have a quantity in this inventory."
            >
              <Box sx={{ height: Math.max(220, scope3SubcategoryRows.length * 28) }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={scope3SubcategoryRows} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={280} tick={{ fontSize: 11 }} />
                    <Tooltip
                      {...tooltipProps}
                      formatter={(value: number, _name, item) => [
                        `${Number(value).toLocaleString()} kg CO₂e`,
                        item?.payload?.full || 'Subcategory',
                      ]}
                    />
                    <Bar dataKey="kg" fill={COUNT_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {subcategoryRows.length > 0 ? (
          <Grid item xs={12} md={7}>
            <ChartCard
              testId="analytics-iso-subcategory-chart"
              title="ISO 14064-1 subcategories"
              subtitle="Subcategories with a stored quantity, largest first."
            >
              <Box sx={{ height: Math.max(220, subcategoryRows.length * 28) }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={subcategoryRows} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={180} tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" fill={ISO_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {hasQuality ? (
          <Grid item xs={12} md={6}>
            <ChartCard
              testId="analytics-quality-chart"
              title="Data-quality kilograms"
              subtitle="Included kilograms by Tier 1 activity, Tier 2 spend, and Tier 3 estimate."
            >
              <Box sx={{ height: 220 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={qualityRows} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" fill={COUNT_COLOR} radius={[4, 4, 0, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {categoryHotspots.length > 0 ? (
          <Grid item xs={12} md={6}>
            <ChartCard
              testId="analytics-category-hotspot-chart"
              title="Largest application categories"
              subtitle="Where the included inventory sits, so the next bill request has a target."
            >
              <Box sx={{ height: Math.max(220, categoryHotspots.length * 28) }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={categoryHotspots} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={140} tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" fill={ISO_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {vendorHotspots.length > 0 ? (
          <Grid item xs={12} md={6}>
            <ChartCard
              testId="analytics-vendor-chart"
              title="Largest vendors"
              subtitle="Suppliers and ledgers that carry the most included kilograms."
            >
              <Box sx={{ height: Math.max(220, vendorHotspots.length * 28) }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={vendorHotspots} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={140} tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" fill={COUNT_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {monthRows.length > 1 ? (
          <Grid item xs={12}>
            <ChartCard
              testId="analytics-month-chart"
              title="Monthly included inventory"
              subtitle="Included kilograms by voucher month."
            >
              <Box sx={{ height: 240 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={monthRows} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                    <YAxis tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [`${Number(value).toLocaleString()} kg CO₂e`, 'Included']} />
                    <Bar dataKey="kg" fill={ISO_COLOR} radius={[4, 4, 0, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {hasCounts ? (
          <Grid item xs={12} md={5}>
            <ChartCard
              testId="analytics-method-chart"
              title="Transaction groups"
              subtitle="Activity-based, spend-based, estimate, excluded, and outside tolerance."
            >
              <Box sx={{ height: 260 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={countRows} layout="vertical" margin={{ top: 8, right: 16, left: 8, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" allowDecimals={false} tick={{ fontSize: 11 }} />
                    <YAxis type="category" dataKey="label" width={130} tick={{ fontSize: 11 }} />
                    <Tooltip {...tooltipProps} formatter={(value: number) => [Number(value).toLocaleString(), 'Transactions']} />
                    <Bar dataKey="count" fill={COUNT_COLOR} radius={[0, 4, 4, 0]} {...animation} />
                  </BarChart>
                </ResponsiveContainer>
              </Box>
            </ChartCard>
          </Grid>
        ) : null}
        {notes.length > 0 ? (
          <Grid item xs={12}>
            <Paper variant="outlined" sx={{ p: 2 }} data-testid="analytics-company-notes">
              <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>What this means for the company</Typography>
              {notes.map((note) => (
                <Typography key={note} variant="body2" color="text.secondary" sx={{ mt: 0.75 }}>
                  {note}
                </Typography>
              ))}
            </Paper>
          </Grid>
        ) : null}
      </Grid>
    </Box>
  );
};

export default CalculationAnalyticsCharts;
